def esc(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
             .replace("'", "\\'").replace('"', '\\"'))

dirs = ["values", "values-pl", "values-sk", "values-fr"]
for i, d in enumerate(dirs):
    path = os.path.join(ROOT, "app/src/main/res", d, "strings.xml")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>', "<resources>"]
    for k, v in S.items():
        attr = ' translatable="false"' if k in ("app_name", "about_sources") else ""
        if attr and i > 0:
            continue
        lines.append(f'    <string name="{k}"{attr}>{esc(v[i])}</string>')
    lines.append("</resources>")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
print(len(S), "strings")
